-- FİKİRLƏŞİRİK — MySQL 8 / utf8mb4. Statuslar ENUM. Pul: amount DECIMAL + currency CHAR(3).
SET NAMES utf8mb4;
CREATE TABLE countries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, iso2 CHAR(2) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, default_currency CHAR(3), is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE locations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, country_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, lat DECIMAL(9,6), lng DECIMAL(9,6), is_active TINYINT(1) NOT NULL DEFAULT 1, KEY(country_id,name), FOREIGN KEY(country_id) REFERENCES countries(id));
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, phone VARCHAR(30) UNIQUE, email VARCHAR(190) UNIQUE, password VARCHAR(255), google_id VARCHAR(64) UNIQUE, country_id INT UNSIGNED, phone_verified_at DATETIME, email_verified_at DATETIME, is_blocked TINYINT(1) NOT NULL DEFAULT 0, terms_accepted_at DATETIME, created_at DATETIME, updated_at DATETIME, deleted_at DATETIME, FOREIGN KEY(country_id) REFERENCES countries(id));
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role ENUM('shipper','carrier','business_owner','admin') NOT NULL, PRIMARY KEY(user_id,role), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE companies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, legal_name VARCHAR(200) NOT NULL, country_id INT UNSIGNED NOT NULL, tax_id VARCHAR(40), contact_person VARCHAR(150), phone VARCHAR(30), email VARCHAR(190), address VARCHAR(255), verification_status ENUM('pending','verified','rejected') NOT NULL DEFAULT 'pending', FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(country_id) REFERENCES countries(id));
CREATE TABLE cargo_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE vehicle_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, is_refrigerated TINYINT(1) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE vehicles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, company_id BIGINT UNSIGNED, vehicle_type_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, brand VARCHAR(60), model VARCHAR(60), capacity_kg INT UNSIGNED NOT NULL, capacity_m3 DECIMAL(8,2), body_type VARCHAR(60), is_refrigerated TINYINT(1) NOT NULL DEFAULT 0, reg_country_id INT UNSIGNED, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(vehicle_type_id) REFERENCES vehicle_types(id));
CREATE TABLE loads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, description TEXT, cargo_type_id INT UNSIGNED, from_country_id INT UNSIGNED NOT NULL, from_location_id INT UNSIGNED, from_address VARCHAR(255), from_lat DECIMAL(9,6), from_lng DECIMAL(9,6), to_country_id INT UNSIGNED NOT NULL, to_location_id INT UNSIGNED, to_address VARCHAR(255), to_lat DECIMAL(9,6), to_lng DECIMAL(9,6), pickup_from DATE NOT NULL, pickup_to DATE, delivery_by DATE, weight_kg DECIMAL(10,2) NOT NULL, volume_m3 DECIMAL(8,2), pallets INT UNSIGNED, required_vehicle_type_id INT UNSIGNED, needs_refrigeration TINYINT(1) NOT NULL DEFAULT 0, temp_min DECIMAL(5,1), temp_max DECIMAL(5,1), is_hazardous TINYINT(1) NOT NULL DEFAULT 0, notes TEXT, price DECIMAL(12,2), currency CHAR(3), price_negotiable TINYINT(1) NOT NULL DEFAULT 1, status ENUM('draft','published','has_applications','agreed','in_transit','completed','cancelled','archived') NOT NULL DEFAULT 'draft', created_at DATETIME, updated_at DATETIME, KEY(status,pickup_from), KEY(from_country_id,to_country_id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE vehicle_offers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, vehicle_id BIGINT UNSIGNED NOT NULL, from_country_id INT UNSIGNED NOT NULL, from_location_id INT UNSIGNED, to_country_id INT UNSIGNED NOT NULL, to_location_id INT UNSIGNED, available_from DATE NOT NULL, available_to DATE NOT NULL, price DECIMAL(12,2), currency CHAR(3), terms TEXT, status ENUM('draft','active','applied','agreed','busy','completed','cancelled','expired') NOT NULL DEFAULT 'draft', created_at DATETIME, updated_at DATETIME, KEY(status,available_to), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id));
CREATE TABLE matches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, load_id BIGINT UNSIGNED NOT NULL, vehicle_offer_id BIGINT UNSIGNED NOT NULL, score TINYINT UNSIGNED NOT NULL, reasons JSON NOT NULL, algorithm_version VARCHAR(20) NOT NULL, calculated_at DATETIME NOT NULL, UNIQUE(load_id,vehicle_offer_id), KEY(score), FOREIGN KEY(load_id) REFERENCES loads(id), FOREIGN KEY(vehicle_offer_id) REFERENCES vehicle_offers(id));
CREATE TABLE applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, load_id BIGINT UNSIGNED NOT NULL, vehicle_offer_id BIGINT UNSIGNED, carrier_id BIGINT UNSIGNED NOT NULL, price DECIMAL(12,2), currency CHAR(3), message VARCHAR(1000), status ENUM('pending','accepted','rejected','withdrawn','cancelled','completed') NOT NULL DEFAULT 'pending', created_at DATETIME, updated_at DATETIME, UNIQUE(load_id,carrier_id), FOREIGN KEY(load_id) REFERENCES loads(id), FOREIGN KEY(carrier_id) REFERENCES users(id));
CREATE TABLE business_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE business_places (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL, name VARCHAR(200) NOT NULL, description TEXT, country_id INT UNSIGNED NOT NULL, location_id INT UNSIGNED, address VARCHAR(255) NOT NULL, lat DECIMAL(9,6) NOT NULL, lng DECIMAL(9,6) NOT NULL, phone VARCHAR(30), website VARCHAR(255), working_hours JSON, services JSON, truck_features JSON, truck_features_verified TINYINT(1) NOT NULL DEFAULT 0, status ENUM('pending','published','rejected','deactivated') NOT NULL DEFAULT 'pending', reject_reason VARCHAR(500), created_at DATETIME, updated_at DATETIME, KEY(status,country_id,category_id), FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE subscription_plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind ENUM('carrier','business_place') NOT NULL, country_id INT UNSIGNED NOT NULL, price DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL, duration_months TINYINT UNSIGNED NOT NULL DEFAULT 1, is_active TINYINT(1) NOT NULL DEFAULT 1, effective_from DATETIME NOT NULL, created_at DATETIME, updated_at DATETIME, KEY(kind,country_id,is_active));
CREATE TABLE place_payment_rules (country_id INT UNSIGNED PRIMARY KEY, payment_required TINYINT(1) NOT NULL DEFAULT 0, updated_at DATETIME);
CREATE TABLE subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, kind ENUM('carrier','business_place') NOT NULL, place_id BIGINT UNSIGNED, country_id INT UNSIGNED NOT NULL, plan_id INT UNSIGNED NOT NULL, status ENUM('active','expired','cancelled','payment_pending','payment_failed','grace') NOT NULL DEFAULT 'payment_pending', starts_at DATETIME, ends_at DATETIME, next_payment_at DATETIME, auto_renew TINYINT(1) NOT NULL DEFAULT 0, last_payment_status VARCHAR(20), cancelled_at DATETIME, cancel_reason VARCHAR(255), KEY(user_id,kind,status), FOREIGN KEY(plan_id) REFERENCES subscription_plans(id));
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, subscription_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, order_id VARCHAR(64) NOT NULL UNIQUE, provider_txn_id VARCHAR(100) UNIQUE, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL, status ENUM('initiated','processing','success','failed','cancelled','refunded') NOT NULL DEFAULT 'initiated', period_applied TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME, updated_at DATETIME, FOREIGN KEY(subscription_id) REFERENCES subscriptions(id));
CREATE TABLE payment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED, event_key VARCHAR(120) NOT NULL UNIQUE, payload JSON, signature_valid TINYINT(1), received_at DATETIME NOT NULL);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, type VARCHAR(60) NOT NULL, data JSON, read_at DATETIME, created_at DATETIME, KEY(user_id,read_at));
CREATE TABLE reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT UNSIGNED NOT NULL, target_type VARCHAR(30) NOT NULL, target_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(500), status ENUM('open','reviewing','resolved','dismissed') NOT NULL DEFAULT 'open', created_at DATETIME);
CREATE TABLE files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, attachable_type VARCHAR(30), attachable_id BIGINT UNSIGNED, path VARCHAR(255) NOT NULL, mime VARCHAR(80), size_bytes INT UNSIGNED, is_private TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED, action VARCHAR(60) NOT NULL, entity VARCHAR(40), entity_id BIGINT UNSIGNED, reason VARCHAR(500), old_values JSON, new_values JSON, ip VARCHAR(45), created_at DATETIME NOT NULL, KEY(entity,entity_id));
CREATE TABLE matching_settings (k VARCHAR(40) PRIMARY KEY, v VARCHAR(100) NOT NULL);
INSERT INTO matching_settings VALUES ('w_route','40'),('w_date','25'),('w_price','20'),('w_capacity','15'),('min_score','30'),('version','1.0');
